insert into public.site_content_blocks
(locale, page_key, slot, eyebrow, title, body, items, cta_label, cta_href, sort_order, is_published)
values
-- EN / HOME
('en', 'home', 'service-depth', 'Locksmith service coverage', 'Complete mobile locksmith service', 'Full-service locksmith help includes emergency lockouts, car keys, rekeys, residential locks, commercial locks, safe opening, access control, and urgent service calls.', '["Emergency, automotive, residential, and commercial service", "Smart locks, safe opening, and access control", "Clear descriptions for customers"]'::jsonb, 'View services', '/en/services', 10, true),
('en', 'home', 'customer-info', 'Before service', 'Information customers should prepare', 'Send the service type, location, urgency, authorization details, contact phone number, and vehicle information when relevant.', '["Service type and exact location", "Authorization or access details", "Vehicle make, model, and year when relevant", "Phone number for confirmation"]'::jsonb, 'Request service', '/en/contact#request-service', 20, true),
('en', 'home', 'area-section', 'Local coverage', 'Mobile service areas', 'Mobile locksmith service is available across Philadelphia and nearby coverage areas for automotive, residential, commercial, and emergency needs.', '["Coverage depends on technician availability", "Response time depends on location and urgency", "Local pages explain common services"]'::jsonb, 'View areas', '/en/areas', 30, true),

-- EN / SERVICE DETAIL
('en', 'service-detail', 'hero', 'Locksmith service', '', 'Service details explain what customers can request, what information is helpful, and what factors may affect availability, pricing, and timing.', '[]'::jsonb, 'Call now', 'tel:+12676122555', 10, true),
('en', 'service-detail', 'overview', 'Service overview', 'What this service includes', 'Service details, preparation steps, and timing factors are confirmed before work begins.', '[]'::jsonb, null, null, 20, true),
('en', 'service-detail', 'readiness', null, 'Information customers should prepare', 'Service type, exact location, phone number, urgency, authorization details, and vehicle information when relevant help make the request actionable.', '["Service type and access details", "Exact location", "Current key, lock, door, safe, mailbox, or vehicle situation", "Phone number for confirmation"]'::jsonb, null, null, 30, true),
('en', 'service-detail', 'pricing', null, 'What affects price and timing', 'Final price and service time may depend on service type, lock or key system, parts availability, programming requirements, distance, time of day, authorization, and job complexity.', '["Lock or key system", "Parts availability", "Programming requirements", "Distance and timing", "Authorization and job complexity"]'::jsonb, null, null, 40, true),
('en', 'service-detail', 'authorization', null, 'Authorization and safety', 'Customers may need to confirm authorization to access or service a vehicle, property, door, lock, safe, mailbox, or access-control system before work begins.', '["Proof of ownership or authorization may be requested", "Details are confirmed before service", "Safety and fraud prevention matter"]'::jsonb, null, null, 50, true),
('en', 'service-detail', 'process', 'How service works', 'Service request process', 'This section explains the customer journey from request to confirmation.', '["Submit service details and location", "Confirm urgency, authorization, and phone number", "Review availability, tools, parts, and compatibility", "Confirm next step before service begins"]'::jsonb, null, null, 60, true),

-- EN / AREA DETAIL
('en', 'area-detail', 'hero', 'Local locksmith coverage', '', 'This area page explains mobile locksmith availability, common services, and customer preparation for this service area.', '[]'::jsonb, 'Call now', 'tel:+12676122555', 10, true),
('en', 'area-detail', 'overview', 'Area overview', 'Mobile coverage information', 'Local service details, common locksmith needs, and preparation notes are listed for this coverage area.', '[]'::jsonb, null, null, 20, true),
('en', 'area-detail', 'prep', null, 'What to prepare before service', 'Customers should prepare service details and location information before requesting mobile service.', '["Service needed and exact location", "Lock, door, safe, mailbox, or access-control details", "Vehicle make, model, and year when relevant", "Whether keys are lost, broken, locked in, or not programming", "Phone number for fast confirmation"]'::jsonb, null, null, 30, true),
('en', 'area-detail', 'supported-services', null, 'Services commonly requested here', 'This section explains common locksmith services requested in local coverage pages.', '["Emergency locksmith 24/7", "Car lockout help", "Rekey service", "Commercial locksmith", "Residential locksmith"]'::jsonb, null, null, 40, true),
('en', 'area-detail', 'local-info', null, 'Local service information', 'Local availability depends on technician schedule, location, service type, parts, traffic, weather, and urgency.', '["Mobile service depends on technician availability and location", "Response times may vary by traffic, distance, weather, and urgency", "Final price depends on service details, parts, authorization, and job complexity"]'::jsonb, null, null, 50, true),
('en', 'area-detail', 'coverage-notes', null, 'Coverage notes', 'Service-area details are confirmed before work begins.', '["Coverage can vary by time and technician availability", "Some services require specific parts or programming tools", "Service details are confirmed before work begins"]'::jsonb, null, null, 60, true),

-- ES / HOME
('es', 'home', 'service-depth', 'Cobertura de cerrajería', 'Servicio móvil completo de cerrajería', 'Ayuda completa para emergencias, llaves de auto, rekeys, cerraduras residenciales, cerraduras comerciales, cajas fuertes, access control y llamadas urgentes.', '["Servicio de emergencia, auto, residencial y comercial", "Smart locks, cajas fuertes y access control", "Descripciones claras para clientes"]'::jsonb, 'Ver servicios', '/es/services', 10, true),
('es', 'home', 'customer-info', 'Antes del servicio', 'Información que el cliente debe preparar', 'Envíe tipo de servicio, ubicación, urgencia, autorización, teléfono y datos del vehículo cuando aplique.', '["Tipo de servicio y ubicación exacta", "Autorización o detalles de acceso", "Marca, modelo y año cuando aplique", "Teléfono para confirmación"]'::jsonb, 'Solicitar servicio', '/es/contact#request-service', 20, true),
('es', 'home', 'area-section', 'Cobertura local', 'Áreas de servicio móvil', 'Servicio móvil de cerrajería en Philadelphia y áreas cercanas para necesidades de auto, hogar, negocio y emergencia.', '["La cobertura depende de disponibilidad", "El tiempo depende de ubicación y urgencia", "Las páginas locales explican servicios comunes"]'::jsonb, 'Ver áreas', '/es/areas', 30, true),

