('es', 'service-detail', 'hero', 'Servicio de cerrajería', '', 'Esta página explica qué puede solicitar el cliente, qué datos ayudan y qué puede afectar disponibilidad, precio y tiempo.', '[]'::jsonb, 'Llamar ahora', 'tel:+12676122555', 10, true),
('es', 'service-detail', 'overview', 'Resumen del servicio', 'Qué incluye este servicio', 'Detalles del servicio, preparación y tiempos se confirman antes de comenzar.', '[]'::jsonb, null, null, 20, true),
('es', 'service-detail', 'readiness', null, 'Información que el cliente debe preparar', 'Tipo de servicio, ubicación exacta, teléfono, urgencia, autorización y datos del vehículo cuando aplique hacen la solicitud más clara.', '["Tipo de servicio y acceso", "Ubicación exacta", "Situación de llave, cerradura, puerta, caja fuerte, buzón o vehículo", "Teléfono para confirmación"]'::jsonb, null, null, 30, true),
('es', 'service-detail', 'pricing', null, 'Qué afecta precio y tiempo', 'El precio y tiempo final pueden depender del tipo de servicio, sistema de cerradura o llave, piezas, programación, distancia, horario, autorización y complejidad.', '["Sistema de cerradura o llave", "Disponibilidad de piezas", "Programación requerida", "Distancia y horario", "Autorización y complejidad"]'::jsonb, null, null, 40, true),
('es', 'service-detail', 'authorization', null, 'Autorización y seguridad', 'El cliente puede necesitar confirmar autorización para acceder o trabajar en vehículo, propiedad, puerta, cerradura, caja fuerte, buzón o access-control antes del servicio.', '["Puede requerirse prueba de autorización", "Los detalles se confirman antes", "La seguridad y prevención de fraude importan"]'::jsonb, null, null, 50, true),
('es', 'service-detail', 'process', 'Cómo funciona el servicio', 'Proceso de solicitud', 'Esta sección explica el camino del cliente desde la solicitud hasta la confirmación.', '["Enviar detalles y ubicación", "Confirmar urgencia, autorización y teléfono", "Revisar disponibilidad, herramientas, piezas y compatibilidad", "Confirmar siguiente paso antes del servicio"]'::jsonb, null, null, 60, true),

