('es', 'area-detail', 'hero', 'Cobertura local de cerrajería', '', 'Esta página explica disponibilidad móvil, servicios comunes y preparación del cliente en esta área.', '[]'::jsonb, 'Llamar ahora', 'tel:+12676122555', 10, true),
('es', 'area-detail', 'overview', 'Resumen del área', 'Información de cobertura móvil', 'Detalles locales, necesidades comunes y preparación se listan para esta área de cobertura.', '[]'::jsonb, null, null, 20, true),
('es', 'area-detail', 'prep', null, 'Qué preparar antes del servicio', 'El cliente debe preparar detalles del servicio y ubicación antes de solicitar servicio móvil.', '["Servicio requerido y ubicación exacta", "Detalles de cerradura, puerta, caja fuerte, buzón o access-control", "Marca, modelo y año cuando aplique", "Si las llaves están perdidas, rotas, encerradas o no programan", "Teléfono para confirmación"]'::jsonb, null, null, 30, true),
('es', 'area-detail', 'supported-services', null, 'Servicios comunes aquí', 'Esta sección explica servicios comunes en páginas locales.', '["Cerrajero de emergencia 24/7", "Bloqueo de automóvil", "Rekey", "Cerrajero comercial", "Cerrajero residencial"]'::jsonb, null, null, 40, true),
('es', 'area-detail', 'local-info', null, 'Información local', 'La disponibilidad local depende de agenda, ubicación, tipo de servicio, piezas, tráfico, clima y urgencia.', '["Servicio móvil depende de disponibilidad y ubicación", "El tiempo varía por tráfico, distancia, clima y urgencia", "El precio depende de servicio, piezas, autorización y complejidad"]'::jsonb, null, null, 50, true),
('es', 'area-detail', 'coverage-notes', null, 'Notas de cobertura', 'Aclare límites de cobertura y expectativas del cliente.', '["La cobertura puede variar por horario y disponibilidad", "Algunos vehículos requieren piezas o herramientas específicas", "Los detalles se confirman antes del servicio"]'::jsonb, null, null, 60, true),

-- RU / HOME
('ru', 'home', 'service-depth', 'Locksmith-сервис', 'Полный мобильный locksmith-сервис', 'Полный сервис включает emergency lockouts, автомобильные ключи, rekeys, residential locks, commercial locks, safe opening, access control и срочные вызовы.', '["Emergency, automotive, residential и commercial service", "Smart locks, safe opening и access control", "Понятные описания для клиентов"]'::jsonb, 'Смотреть услуги', '/ru/services', 10, true),
('ru', 'home', 'customer-info', 'Перед сервисом', 'Что клиенту подготовить', 'Отправьте тип услуги, локацию, срочность, право доступа, телефон и данные автомобиля, когда это применимо.', '["Тип услуги и точная локация", "Авторизация или детали доступа", "Марка, модель и год когда применимо", "Телефон для подтверждения"]'::jsonb, 'Оставить заявку', '/ru/contact#request-service', 20, true),
('ru', 'home', 'area-section', 'Локальное покрытие', 'Районы мобильного сервиса', 'Мобильный locksmith-сервис доступен в Philadelphia и ближайших районах для авто, дома, бизнеса и срочных ситуаций.', '["Покрытие зависит от доступности", "Время зависит от локации и срочности", "Локальные страницы объясняют частые услуги"]'::jsonb, 'Смотреть районы', '/ru/areas', 30, true),

-- RU / SERVICE DETAIL
('ru', 'service-detail', 'hero', 'Locksmith-услуга', '', 'Эта страница объясняет, что клиент может запросить, какие данные помогают и что влияет на доступность, цену и сроки.', '[]'::jsonb, 'Позвонить', 'tel:+12676122555', 10, true),
('ru', 'service-detail', 'overview', 'Описание услуги', 'Что включает услуга', 'Детали услуги, подготовка и сроки подтверждаются до начала работы.', '[]'::jsonb, null, null, 20, true),
('ru', 'service-detail', 'readiness', null, 'Что клиенту подготовить', 'Тип услуги, точная локация, телефон, срочность, право доступа и данные автомобиля когда применимо помогают быстрее подготовить сервис.', '["Тип услуги и детали доступа", "Точная локация", "Ситуация с ключом, замком, дверью, сейфом, mailbox или авто", "Телефон для подтверждения"]'::jsonb, null, null, 30, true),
('ru', 'service-detail', 'pricing', null, 'Что влияет на цену и сроки', 'Финальная цена и время могут зависеть от типа услуги, системы замка или ключа, наличия деталей, программирования, расстояния, времени, авторизации и сложности.', '["Система замка или ключа", "Наличие деталей", "Необходимость программирования", "Расстояние и время", "Авторизация и сложность"]'::jsonb, null, null, 40, true),
('ru', 'service-detail', 'authorization', null, 'Авторизация и безопасность', 'Клиенту может потребоваться подтвердить право доступа к автомобилю, property, двери, замку, сейфу, mailbox или access-control system до начала работы.', '["Может потребоваться подтверждение права", "Детали подтверждаются до начала", "Безопасность и защита от мошенничества важны"]'::jsonb, null, null, 50, true),
('ru', 'service-detail', 'process', 'Как проходит сервис', 'Процесс заявки', 'Этот блок объясняет путь клиента от заявки до подтверждения.', '["Отправить детали услуги и локацию", "Подтвердить срочность, авторизацию и телефон", "Проверить доступность, инструменты, детали и совместимость", "Подтвердить следующий шаг до начала услуги"]'::jsonb, null, null, 60, true),

-- RU / AREA DETAIL
('ru', 'area-detail', 'hero', 'Локальное locksmith-покрытие', '', 'Эта страница объясняет мобильную доступность, частые услуги и подготовку клиента в этом районе.', '[]'::jsonb, 'Позвонить', 'tel:+12676122555', 10, true),
('ru', 'area-detail', 'overview', 'Описание района', 'Информация о мобильном покрытии', 'Локальные детали сервиса, частые locksmith-задачи и подготовка указаны для этого района.', '[]'::jsonb, null, null, 20, true),
('ru', 'area-detail', 'prep', null, 'Что подготовить перед услугой', 'Клиент должен подготовить детали услуги и локацию перед запросом мобильного сервиса.', '["Нужная услуга и точная локация", "Детали замка, двери, сейфа, mailbox или access-control", "Марка, модель и год когда применимо", "Потеряны, сломаны, закрыты внутри или не программируются ли ключи", "Телефон для быстрого подтверждения"]'::jsonb, null, null, 30, true),
('ru', 'area-detail', 'supported-services', null, 'Частые услуги здесь', 'Этот блок объясняет частые locksmith-услуги на локальных страницах.', '["Emergency locksmith 24/7", "Car lockout help", "Rekey service", "Commercial locksmith", "Residential locksmith"]'::jsonb, null, null, 40, true),
('ru', 'area-detail', 'local-info', null, 'Локальная информация', 'Локальная доступность зависит от графика, локации, типа услуги, деталей, трафика, погоды и срочности.', '["Мобильный сервис зависит от доступности и локации", "Сроки зависят от трафика, расстояния, погоды и срочности", "Цена зависит от услуги, деталей, авторизации и сложности"]'::jsonb, null, null, 50, true),
('ru', 'area-detail', 'coverage-notes', null, 'Заметки по покрытию', 'Уточните ограничения покрытия и ожидания клиента.', '["Покрытие может меняться по времени и доступности", "Некоторые авто требуют специальные детали или инструменты", "Детали подтверждаются до начала услуги"]'::jsonb, null, null, 60, true)
on conflict do nothing;
